import { Card } from '@/components/ds/ui/card';
import { DotGrid } from '@/components/ds/ui/dot-grid';
import { Section } from '@/components/ds/ui/section';
import { SectionHeading } from '@/components/ds/ui/section-heading';

export type BlogGridProps = {
	title: string;
	highlight?: string;
	posts: { title: string; date: string; excerpt: string; href: string; art: string[] }[];
};

export function BlogGrid({ title, highlight, posts }: BlogGridProps) {
	return (
		<Section block="blog-grid" surface="black">
			<div className="flex flex-col gap-10">
				<SectionHeading title={title} highlight={highlight} tone="inverse" />
				<div className="grid gap-4 md:grid-cols-3">
					{posts.slice(0, 6).map((post, i) => (
						<a key={post.href} href={post.href} className="block focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus">
							<Card tone={i % 2 === 1 ? 'blue' : 'white'}>
								<div className="flex justify-center py-4"><DotGrid pattern={post.art} tone={i % 2 === 1 ? 'on-brand' : 'on-white'} size="sm" /></div>
								<p className="text-caption">{post.date}</p>
								<h3 className="line-clamp-2 text-h5">{post.title}</h3>
								<p className="line-clamp-2 text-body-sm">{post.excerpt}</p>
							</Card>
						</a>
					))}
				</div>
			</div>
		</Section>
	);
}
